const P = { pc: '31393214664f295f94dd86.76792605', members: '9933660066825e9a8005c8.58526829', mindspree: '2746345369c281440b9d57.82826222' };
const out = [];
for (const [t, id] of Object.entries(P)) for (const page of [1, 2, 3, 4]) out.push({ json: { t, url: 'https://api.lokalise.com/api2/projects/' + id + '/keys?include_translations=1&disable_references=1&filter_translation_lang_ids=640&limit=5000&page=' + page } });
return out;

const src = $('Build URLs').all();
const D = { pc: [], members: [], mindspree: [] }; const bad = [];
$input.all().forEach((it, i) => { const t = src[i].json.t; const b = it.json;
  if (!Array.isArray(b.keys)) { bad.push(t + ':' + i); return; }
  for (const k of b.keys) { if (k.is_archived) continue; const kn = typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || Object.values(k.key_name)[0]) : k.key_name;
    const tr = (k.translations || []).find(x => x.language_iso === 'en' || x.language_id === 640); if (!tr) continue;
    let txt = tr.translation; if (k.is_plural && typeof txt === 'string') { try { const o = JSON.parse(txt); txt = o.other || o.one || Object.values(o)[0] || ''; } catch (e) {} }
    if (typeof txt !== 'string' || !txt.trim()) continue; D[t].push([kn, txt, (k.tags || []).join('|')]); } });
const norm = s => s.replace(/<[^>]+>/g, ' ').replace(/\{\{[^}]*\}\}|\{[^}]*\}|\[%[^\]]*\]|%\d*\$?[sd@]/g, ' PH ').replace(/&nbsp;|\u00a0/g, ' ').replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"').replace(/[\u2013\u2014]/g, '-').toLowerCase().replace(/\s+/g, ' ').replace(/[\s.!?:;,…]+$/, '').trim();
const toks = s => Array.from(new Set(s.split(/[^\p{L}\p{N}]+/u).filter(w => w.length > 1)));
const words = s => (s.replace(/<[^>]+>/g, ' ').match(/[\p{L}\p{N}]+/gu) || []).length;
function lev(a, b) { if (a === b) return 0; const m = a.length, n = b.length; if (!m) return n; if (!n) return m; let p = new Array(n + 1), c = new Array(n + 1); for (let j = 0; j <= n; j++) p[j] = j; for (let i = 1; i <= m; i++) { c[0] = i; const ai = a.charCodeAt(i - 1); for (let j = 1; j <= n; j++) { c[j] = Math.min(p[j] + 1, c[j - 1] + 1, p[j - 1] + (ai === b.charCodeAt(j - 1) ? 0 : 1)); } [p, c] = [c, p]; } return p[n]; }
const corpus = []; const exact = new Map(), nmap = new Map(); const inv = new Map();
for (const t of ['pc', 'members']) for (const [kn, txt] of D[t]) { const n = norm(txt); const idx = corpus.length; corpus.push({ t, kn, txt, n });
  if (!exact.has(txt)) exact.set(txt, idx); if (!nmap.has(n)) nmap.set(n, idx);
  for (const w of toks(n)) { if (!inv.has(w)) inv.set(w, []); inv.get(w).push(idx); } }
const band = s => s >= 100 ? '100' : s >= 95 ? '95-99' : s >= 85 ? '85-94' : s >= 75 ? '75-84' : s >= 50 ? '50-74' : '<50';
const rows = []; const agg = {}; const aggW = {}; let totW = 0;
for (const [kn, txt, tags] of D.mindspree) { const n = norm(txt); const w = words(txt); totW += w; let cls, score = 0, bi = -1;
  if (exact.has(txt)) { cls = '100 exact'; score = 100; bi = exact.get(txt); }
  else if (nmap.has(n)) { cls = '100 normalized'; score = 100; bi = nmap.get(n); }
  else { const tk = toks(n); const cnt = new Map();
    for (const w2 of tk) { const l = inv.get(w2); if (!l || l.length > 3000) continue; for (const x of l) cnt.set(x, (cnt.get(x) || 0) + 1); }
    const cand = [...cnt.entries()].map(([x, c]) => [x, 2 * c / (tk.length + toks(corpus[x].n).length)]).sort((a, b) => b[1] - a[1]).slice(0, 15);
    for (const [x] of cand) { const cn = corpus[x].n; if (Math.abs(cn.length - n.length) > Math.max(n.length, cn.length) * 0.6) continue; if (n.length > 1500 || cn.length > 1500) continue;
      const s = Math.round(100 * (1 - lev(n, cn) / Math.max(n.length, cn.length))); if (s > score) { score = s; bi = x; } }
    if (score >= 100) score = 99; cls = band(score); }
  agg[cls] = (agg[cls] || 0) + 1; aggW[cls] = (aggW[cls] || 0) + w;
  const b = bi >= 0 ? corpus[bi] : null; rows.push([kn, txt.slice(0, 400), tags, cls, score, w, b ? b.t : '', b ? b.kn : '', b ? b.txt.slice(0, 400) : '']); }
const mEx = new Set(D.mindspree.map(r => norm(r[1]))); const rev = {};
for (const t of ['pc', 'members']) { const u = new Set(D[t].map(r => norm(r[1]))); let hit = 0; for (const x of u) if (mEx.has(x)) hit++; rev[t] = { keys: D[t].length, unique: u.size, uniqueInMindspree: hit }; }
return [{ json: { bad, counts: { pc: D.pc.length, members: D.members.length, mindspree: D.mindspree.length }, totW, agg, aggW, rev, rows } }];
